// Xcode 27 refuses to build targets whose iOS deployment target is below 15.0,
// and a few pods (lottie, AsyncStorage, SDWebImage) still declare 9.0–13.4.
// This plugin adds a post_install step to the generated Podfile that raises every
// pod target to the app's own deployment target. `ios/` is regenerated by prebuild,
// so the fix has to live here rather than in the Podfile itself.
const { withPodfile, WarningAggregator } = require("expo/config-plugins");

const MARKER = "# @horosho/pod-deployment-target";

const SNIPPET = `
    ${MARKER}
    min_target = podfile_properties['ios.deploymentTarget'] || '15.1'
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |build_config|
        current = build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        if current.nil? || Gem::Version.new(current) < Gem::Version.new(min_target)
          build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = min_target
        end
      end
    end
`;

// The whole `react_native_post_install(...)` call, up to its closing parenthesis.
const ANCHOR = /react_native_post_install\([\s\S]*?\n\s*\)\n/;

module.exports = function withPodDeploymentTarget(config) {
  return withPodfile(config, (config) => {
    const { contents } = config.modResults;
    if (contents.includes(MARKER)) return config;

    if (!ANCHOR.test(contents)) {
      WarningAggregator.addWarningIOS(
        "withPodDeploymentTarget",
        "Не нашёл react_native_post_install в Podfile — минимальная версия iOS для подов не поднята."
      );
      return config;
    }

    config.modResults.contents = contents.replace(
      ANCHOR,
      (match) => match + SNIPPET
    );
    return config;
  });
};
